using System.Net;using System.Net.Http.Json;using System.Text.Json;
namespace Commerce.Operations.Api.Settlements;
public sealed class SettlementGateway(HttpClient client){private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);public Task<SettlementPage> ListAsync(DateOnly from,DateOnly to)=>Send<SettlementPage>(HttpMethod.Get,$"/internal/settlements?from={from:yyyy-MM-dd}&to={to:yyyy-MM-dd}");public Task<RebuildResult> RebuildAsync(DateOnly from,DateOnly to)=>Send<RebuildResult>(HttpMethod.Post,$"/internal/settlements/rebuild?from={from:yyyy-MM-dd}&to={to:yyyy-MM-dd}");private async Task<T> Send<T>(HttpMethod method,string path){using var response=await client.SendAsync(new HttpRequestMessage(method,path));if(!response.IsSuccessStatusCode)throw new SettlementGatewayException(response.StatusCode,await response.Content.ReadAsStringAsync());return await response.Content.ReadFromJsonAsync<T>(Json)??throw new InvalidOperationException("Order engine returned an empty response.");}}
public sealed class SettlementGatewayException(HttpStatusCode status,string detail):Exception(detail){public HttpStatusCode StatusCode{get;}=status;}
